# Panel 4: FinnPRIO ENT3 write-up, one per selected pathway. Editable plain text
# with a Copy button. Generated by the LLM (R/prompts.R) from the deterministic
# results, validated, and labelled; falls back to a draft built only from
# Panel 1 numbers when the LLM output fails validation or the call fails.

writeup_draft <- function(r, pathway, settings, inputs = NULL) {
  if (pathway_type(pathway) == "manual") return("")
  cl <- r$classes[r$classes$pathway == pathway & r$classes$role == "ent3", ]
  if (nrow(cl) == 0) return("")
  law <- r$law[r$law$pest_match, ]
  cite <- if (nrow(law) > 0) paste0(" Regulated: ", law$id[1], ".") else " Not found in FOR-2000-12-01-1333."
  main <- ""
  if (!is.null(inputs$lines) && nrow(inputs$lines) > 0 && inputs$lines$kg[1] > 0) {
    top <- utils::head(inputs$lines[inputs$lines$kg > 0, ], 3)
    main <- paste0(" Main CN8 lines: ", paste0(top$code, " ", fmt_num(top$kg), " kg", collapse = ", "), ".")
  }
  pres <- ""
  if (!is.null(inputs$present)) {
    p <- inputs$present[inputs$present$kg > 0, ]
    pres <- if (nrow(p) == 0) " No recorded imports from pest-present countries." else
      paste0(" From pest-present countries: ", paste0(utils::head(p$name, 4), " ", fmt_num(utils::head(p$kg, 4)), " kg",
                                                      collapse = ", "), ".")
  }
  txt <- paste0(pathway_label(pathway), ": ENT3 is ", cl$class, ". All host commodities ",
                fmt_num(cl$kg), " kg/yr (", cl$stat, " ", cl$years, ").", main, pres, cite)
  substr(txt, 1, settings$writeup_max_chars)
}

writeup_label <- function(w) {
  if (w$source == "draft") {
    paste0("Draft from Panel 1 numbers (LLM output rejected: ", paste(w$problems, collapse = "; "), ").")
  } else if (startsWith(w$source, "error")) {
    paste0("Draft from Panel 1 numbers (LLM call failed: ", sub("^error: ", "", w$source), ").")
  } else {
    paste0("Generated by LLM (", w$source, "). Check before pasting into FinnPRIO.")
  }
}

mod_writeup_ui <- function(id) {
  ns <- shiny::NS(id)
  shiny::tagList(
    shiny::uiOutput(ns("boxes")),
    shiny::actionButton(ns("regenerate"), "Regenerate", class = "btn-sm btn-outline-secondary")
  )
}

mod_writeup_server <- function(id, result, pathways, settings) {
  shiny::moduleServer(id, function(input, output, session) {
    texts <- shiny::reactive({
      r <- result()
      shiny::req(is.list(r), !inherits(r, "condition"))
      nonce <- input$regenerate
      p <- intersect(pathways(), computed_pathways)
      shiny::withProgress(message = "Writing ENT3 text", value = 0.5, {
        stats::setNames(lapply(p, function(x) {
          tryCatch(generate_writeup(r, x, settings, nonce = nonce), error = function(e) {
            list(text = writeup_draft(r, x, settings), source = paste0("error: ", conditionMessage(e)),
                 problems = character())
          })
        }), p)
      })
    })

    output$boxes <- shiny::renderUI({
      w <- texts()
      lapply(pathways(), function(p) {
        box_id <- session$ns(paste0("text_", p))
        head <- shiny::tags$label(class = "fw-semibold", `for` = box_id, pathway_label(p))
        if (pathway_type(p) == "manual") {
          return(shiny::div(class = "mb-3", head, shiny::p(class = "text-muted", "Assess manually (not computed in v1).")))
        }
        x <- w[[p]]
        shiny::div(class = "mb-3", head,
          shiny::p(class = "small text-muted mb-1", writeup_label(x)),
          shiny::textAreaInput(box_id, NULL, value = x$text, width = "100%", rows = 3, resize = "vertical"),
          shiny::div(class = "d-flex gap-2 align-items-center",
            copy_button(box_id, "Copy"),
            shiny::span(class = "small text-muted", paste0(nchar(x$text), " / ", settings$writeup_max_chars, " characters"))))
      })
    })
  })
}
